//! Known-answer tests.
//!
//! 1. The published BIP 324 packet-encoding vectors (`bip-0324/packet_encoding_test_vectors.csv`,
//!    bitcoin/bips master, fetched 2026-10-23) with the Bitcoin salt. They pin the ECDH, the key
//!    schedule, both ciphers, rekeying and the packet layout byte for byte.
//! 2. ZKas-salt vectors generated by the BIP 324 reference implementation (`reference.py`) with the
//!    salt changed to `b"zkas_v2_shared_secret" || BLAKE2b-256(network_name)[0..4]`, so the ZKas
//!    variant is checked against an independent implementation too.

use kaspa_zkt2::cipher::{PacketEncryptor, SessionKeys, bitcoin_salt, zkas_salt};
use kaspa_zkt2::stream::{Role, ecdh_secret};
use secp256k1::SecretKey;
use secp256k1::ellswift::ElligatorSwift;
use std::collections::HashMap;

fn rows(csv: &str) -> Vec<HashMap<String, String>> {
    let mut lines = csv.lines();
    let header: Vec<String> = lines.next().unwrap().split(',').map(|s| s.trim().to_string()).collect();
    lines
        .filter(|l| !l.trim().is_empty())
        .map(|l| header.iter().cloned().zip(l.split(',').map(|s| s.trim().to_string())).collect())
        .collect()
}

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap()
}

fn arr32(s: &str) -> [u8; 32] {
    h(s).try_into().unwrap()
}

fn arr16(s: &str) -> [u8; 16] {
    h(s).try_into().unwrap()
}

fn run(row: &HashMap<String, String>, salt: &[u8]) {
    let sk = SecretKey::from_slice(&h(&row["in_priv_ours"])).unwrap();
    let ours = ElligatorSwift::from_array(h(&row["in_ellswift_ours"]).try_into().unwrap());
    let theirs = ElligatorSwift::from_array(h(&row["in_ellswift_theirs"]).try_into().unwrap());
    let initiating = row["in_initiating"] == "1";
    let role = if initiating { Role::Initiator } else { Role::Responder };

    let secret = ecdh_secret(&ours, &theirs, sk, role);
    assert_eq!(secret, arr32(&row["mid_shared_secret"]), "shared secret");

    let keys = SessionKeys::derive(&secret, salt);
    assert_eq!(keys.initiator_l, arr32(&row["mid_initiator_l"]));
    assert_eq!(keys.initiator_p, arr32(&row["mid_initiator_p"]));
    assert_eq!(keys.responder_l, arr32(&row["mid_responder_l"]));
    assert_eq!(keys.responder_p, arr32(&row["mid_responder_p"]));
    let (send_term, recv_term) = if initiating {
        (keys.initiator_garbage_terminator, keys.responder_garbage_terminator)
    } else {
        (keys.responder_garbage_terminator, keys.initiator_garbage_terminator)
    };
    assert_eq!(send_term, arr16(&row["mid_send_garbage_terminator"]));
    assert_eq!(recv_term, arr16(&row["mid_recv_garbage_terminator"]));
    assert_eq!(keys.session_id, arr32(&row["out_session_id"]));

    let mut enc = if initiating {
        PacketEncryptor::new(keys.initiator_l, keys.initiator_p)
    } else {
        PacketEncryptor::new(keys.responder_l, keys.responder_p)
    };
    let idx: usize = row["in_idx"].parse().unwrap();
    let mut sink = Vec::new();
    for _ in 0..idx {
        sink.clear();
        enc.encrypt_packet(&[], &[], true, &mut sink);
    }
    let multiply: usize = row["in_multiply"].parse().unwrap();
    let contents = h(&row["in_contents"]).repeat(multiply);
    let aad = h(&row["in_aad"]);
    let ignore = row["in_ignore"] == "1";
    let mut ct = Vec::new();
    enc.encrypt_packet(&contents, &aad, ignore, &mut ct);

    match row.get("out_ciphertext").filter(|s| !s.is_empty()) {
        Some(full) => assert_eq!(hex::encode(&ct), *full, "ciphertext"),
        None => {
            let tail = h(&row["out_ciphertext_endswith"]);
            assert!(ct.ends_with(&tail), "ciphertext tail");
        }
    }
}

#[test]
fn bip324_published_packet_vectors() {
    let csv = include_str!("data/bip324_packet_encoding_test_vectors.csv");
    let rows = rows(csv);
    assert_eq!(rows.len(), 7, "the published file has 7 vectors");
    let salt = bitcoin_salt([0xf9, 0xbe, 0xb4, 0xd9]);
    for row in &rows {
        run(row, &salt);
    }
}

#[test]
fn zkt2_vectors_from_the_reference_implementation() {
    let csv = include_str!("data/zkt2_packet_vectors.csv");
    let rows = rows(csv);
    assert_eq!(rows.len(), 6);
    for row in &rows {
        run(row, &zkas_salt(&row["network"]));
    }
}
